  1→'use client';
  2→
  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
  5→import { loadVimeoPlayer } from '@/lib/vimeo';
  6→import { useIsMobile } from '@/lib/hooks/useIsMobile';
  7→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
  8→
  9→/**
 10→ * HERO REEL - Homepage Autoplay Video
 11→ *
 12→ * Consistency guarantees:
 13→ * 1. Deterministic initialization with timeout (12s max)
 14→ * 2. Clean error handling with fallback to static state
 15→ * 3. Proper cleanup on unmount
 16→ * 4. Scroll-based pause/resume with ref tracking
 17→ * 5. Mobile optimization: static thumbnail only (no video player)
 18→ * 6. Error event listeners for runtime failures
 19→ */
 20→
 21→// Timeout for player initialization (12 seconds - supports slow connections)
 22→const INIT_TIMEOUT_MS = 12000;
 23→
 24→interface HeroReelProps {
 25→  videoId: string;
 26→  videoHash?: string;
 27→  startTime?: number;
 28→  thumbnail?: string;
 29→}
 30→
 31→export function HeroReel({ videoId, videoHash, startTime = 0, thumbnail }: HeroReelProps) {
 32→  const containerRef = useRef<HTMLDivElement>(null);
 33→  const playerRef = useRef<Player | null>(null);
 34→  const isReadyRef = useRef(false);
 35→  const scrolledDownRef = useRef(false);
 36→
 37→  const [scrollProgress, setScrollProgress] = useState(0);
 38→  const [heroRevealed, setHeroRevealed] = useState(false);
 39→  const [videoPlaying, setVideoPlaying] = useState(false);
 40→
 41→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 42→  const prefersReducedMotion = usePrefersReducedMotion();
 43→
 44→  // Thumbnail URL - use provided thumbnail or fallback to Vimeo vumbnail
 45→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
 46→
 47→  // Hero height based on device
 48→  const heroHeight = isMobile ? '50vh' : '70vh';
 49→
 50→  // Clean destroy of player instance
 51→  const destroyPlayer = useCallback(() => {
 52→    if (playerRef.current) {
 53→      try {
 54→        playerRef.current.destroy();
 55→      } catch {
 56→        // Player may already be destroyed
 57→      }
 58→      playerRef.current = null;
 59→    }
 60→    isReadyRef.current = false;
 61→  }, []);
 62→
 63→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 64→  useEffect(() => {
 65→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 66→    return () => clearTimeout(revealTimer);
 67→  }, []);
 68→
 69→  // Initialize Vimeo player with autoplay (desktop only)
 70→  useEffect(() => {
 71→    // Wait for mobile detection to complete before deciding
 72→    if (!isMobileReady) return;
 73→
 74→    // Skip player initialization on mobile - use static thumbnail instead
 75→    if (isMobile) return;
 76→
 77→    if (!containerRef.current) return;
 78→
 79→    const baseConfig = {
 80→      muted: true,
 81→      loop: true,
 82→      autoplay: true,
 83→      controls: false,
 84→      background: true,
 85→      responsive: true,
 86→      title: false,
 87→      byline: false,
 88→      portrait: false,
 89→      dnt: true,
 90→      playsinline: true,
 91→      quality: 'auto',
 92→      speed: true,
 93→      transparent: false, // Request dark player background from Vimeo
 94→    };
 95→
 96→    const baseUrl = videoHash
 97→      ? `https://vimeo.com/${videoId}/${videoHash}`
 98→      : `https://vimeo.com/${videoId}`;
 99→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
100→
101→    let isMounted = true;
102→
103→    const initPlayer = async () => {
104→      try {
105→        const VimeoPlayer = await loadVimeoPlayer();
106→        if (!isMounted || !containerRef.current) return;
107→
108→        playerRef.current = new VimeoPlayer(containerRef.current!, {
109→          url: urlWithTime as `https://vimeo.com/${string}`,
110→          ...baseConfig
111→        });
112→
113→        // Race between ready() and timeout
114→        const readyPromise = playerRef.current.ready();
115→        const timeoutPromise = new Promise<never>((_, reject) => {
116→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
117→        });
118→
119→        await Promise.race([readyPromise, timeoutPromise]);
120→
121→        if (!isMounted) {
122→          destroyPlayer();
123→          return;
124→        }
125→
126→        isReadyRef.current = true;
127→
128→        // Add error event listener for runtime failures
129→        playerRef.current.on('error', (error) => {
130→          console.error('HeroReel: Player error', videoId, error);
131→        });
132→
133→        // Wait for video to actually start rendering frames before revealing.
134→        // 'bufferend' fires when enough data is buffered to play without interruption.
135→        // 'playing' fires when playback actually begins after buffering.
136→        // Ultimate fallback: reveal after INIT_TIMEOUT_MS regardless.
137→        const revealOnce = () => {
138→          if (isMounted) setVideoPlaying(true);
139→        };
140→        playerRef.current.on('bufferend', revealOnce);
141→        playerRef.current.on('playing', revealOnce);
142→
143→        // Start playback (may already be playing via background autoplay)
144→        await playerRef.current.play().catch(() => {});
145→      } catch (err) {
146→        console.error('HeroReel: Player init failed', videoId, err);
147→        destroyPlayer();
148→      }
149→    };
150→
151→    initPlayer();
152→
153→    return () => {
154→      isMounted = false;
155→      destroyPlayer();
156→    };
157→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
158→
159→  // Track scroll for fade and pause/resume
160→  useEffect(() => {
161→    const handleScroll = () => {
162→      const scrollY = window.scrollY;
163→      const viewportHeight = window.innerHeight;
164→      // Use appropriate hero height multiplier based on device
165→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
166→      const introPadding = 160;
167→      const textStartPosition = heroHeightValue + introPadding;
168→      const oneThirdViewport = viewportHeight / 3;
169→      const fadeStartScroll = textStartPosition - oneThirdViewport;
170→
171→      const fadeRange = 200;
172→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
173→      setScrollProgress(progress);
174→
175→      // Pause/resume with ref tracking for consistency (desktop only)
176→      if (!isMobile) {
177→        const hasScrolledDown = scrollY > 10;
178→
179→        if (hasScrolledDown && !scrolledDownRef.current) {
180→          scrolledDownRef.current = true;
181→          if (playerRef.current && isReadyRef.current) {
182→            playerRef.current.pause().catch(() => {});
183→          }
184→        } else if (!hasScrolledDown && scrolledDownRef.current) {
185→          scrolledDownRef.current = false;
186→          if (playerRef.current && isReadyRef.current) {
187→            playerRef.current.play().catch(() => {});
188→          }
189→        }
190→      }
191→    };
192→
193→    // Run immediately to sync initial state
194→    handleScroll();
195→
196→    window.addEventListener('scroll', handleScroll, { passive: true });
197→    return () => window.removeEventListener('scroll', handleScroll);
198→  }, [isMobile]);
199→
200→  const scrollOpacity = 1 - scrollProgress;
201→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
202→  const heroScale = heroRevealed ? 1 : 1.02;
203→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
204→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
205→
206→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
207→  // This ensures scroll-driven fade is perfectly synchronized with navigation
208→  const heroTransition = heroRevealed
209→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
210→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
211→
212→  return (
213→    <div
214→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
215→      style={{
216→        height: heroHeight,
217→        zIndex: 0,
218→        backgroundColor: '#141414',
219→        // Exclude from view transition snapshot — prevents white flash
220→        // when Vimeo iframe is destroyed/recreated during page transitions
221→        viewTransitionName: 'hero-reel',
222→      }}
223→    >
224→      <div
225→        style={{
226→          width: '100%',
227→          height: '100%',
228→          opacity: heroOpacity,
229→          transform: `scale(${heroScale})`,
230→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
231→          transition: heroTransition,
232→          transformOrigin: 'center center',
233→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
234→        }}
235→      >
236→        {!isMobile && (
237→          // Desktop: Vimeo player container (behind thumbnail until video plays)
238→          <div
239→            ref={containerRef}
240→            className="absolute inset-0 w-full h-full"
241→            style={{
242→              backgroundColor: '#141414',
243→              zIndex: 0
244→            }}
245→          />
246→        )}
247→        {/* Thumbnail overlay - sits ABOVE iframe, masks white flash until video plays.
248→            Uses the actual video thumbnail for seamless transition to video. */}
249→        <div
250→          className="absolute inset-0 w-full h-full"
251→          style={{
252→            backgroundImage: `url(${thumbnailUrl})`,
253→            backgroundSize: 'cover',
254→            backgroundPosition: 'center',
255→            backgroundColor: '#141414',
256→            zIndex: 1,
257→            opacity: videoPlaying ? 0 : 1,
258→            transition: 'opacity 0.4s ease-out',
259→            pointerEvents: 'none'
260→          }}
261→        />
262→      </div>
263→    </div>
264→  );
265→}
